use job_tracker_web::{api, config::Config, service, AppState};
#[tokio::main] async fn main(){tracing_subscriber::fmt().with_env_filter(tracing_subscriber::EnvFilter::from_default_env()).init();let config=Config::from_env().expect("valid server configuration");let bind=config.bind;let state=AppState::connect(config).await.expect("database connection and migrations");match service::abandon_interrupted_runs(&state,false).await{Ok(0)=>{},Ok(count)=>tracing::warn!(count,"marked searches interrupted by a restart as abandoned"),Err(error)=>tracing::error!(%error,"could not clean up interrupted searches")}let listener=tokio::net::TcpListener::bind(bind).await.expect("bind API");tracing::info!(%bind,"Job Tracker web API ready");axum::serve(listener,api::router(state)).await.expect("API server");}
